export const Clock = tag<{ now(): number }>('Clock')
export const Db = tag<{ query(sql: string): string[] }>('Db')
export const Cache = tag<{ get(k: string): string[] }>('Cache')

const ClockLive = layer(Clock, { now: () => Date.now() }, [], { lifetime: 'app' })
const DbLive = layer(Db, { query: (sql: string) => [sql] }, [], { lifetime: 'request' })
const CacheLive = layer(Cache, (db) => ({ get: (k: string) => db.query(k) }), [Db], { lifetime: 'app' })

export const Data = module({ name: 'Data', provide: [ClockLive, DbLive, CacheLive], exports: [Clock, Db, Cache] })

