import { layer, module, tag } from '@sleekstack/kit'

export const Clock = tag<{ now(): number }>('Clock')
export const A = tag<{ a(): number }>('A')
export const B = tag<{ b(): number }>('B')

const ClockLive = layer(Clock, { now: () => Date.now() }, [], { lifetime: 'app' })
const ALive = layer(A, (b, c) => ({ a: () => b.b() + c.now() }), [B, Clock])
const BLive = layer(B, (a) => ({ b: () => a.a() }), [A])

export const Data = module({ name: 'Data', provide: [ClockLive, ALive, BLive], exports: [Clock, A, B] })

